type Pengguna = { id: number; nama: string; email: string; password: string };
type PenggunaPublik = Omit<Pengguna, "password">;

function publik(u: Pengguna): PenggunaPublik {
  const { password, ...sisa } = u;
  return sisa;
}
type Status = "aktif" | "diblokir";
const jumlah: Record<Status, number> = { aktif: 0, diblokir: 0 };

const rina: Pengguna = { id: 1, nama: "Rina", email: "rina@contoh.id", password: "rahasia" };
console.log(Object.keys(publik(rina)).join(","));
jumlah.aktif += 2;
console.log(jumlah.aktif, jumlah.diblokir);

