type Bahasa = "id" | "en";
const SALAM: Record<Bahasa, string> = { id: "Halo", en: "Hello" };
function sapa(b: Bahasa, nama: string): string {
  return SALAM[b] + " " + nama;
}
console.log(sapa("en", "Rina"));
console.log(sapa("id", "Budi"));
